 const screens=[...document.querySelectorAll('.screen')],q=id=>document.getElementById(id);
 function levelName(n){const w=Math.floor((n-1)/5),i=(n-1)%5;return CAMPAIGN[w]?.levels[i]||'Nivel'}
 function heroDef(){return CAT.heroBases.find(h=>h.id===MC.state.data.avatar.heroBase)||CAT.heroBases[0]}
 function navRaw(name){screens.forEach(s=>s.classList.toggle('active',s.dataset.screen===name))}
 function nav(name){if(name!=='game'&&MC.game){MC.game.running=false;MC.game.music?.stop();MC.game.toggleInventory?.(false);document.getElementById('bonus-briefing-overlay')?.classList.add('hidden')}navRaw(name);if(name==='home')renderHome();if(name==='creator')renderCreator();if(name==='campaign')renderCampaign();if(name==='collection')renderCollection();if(name==='store')renderStore();if(name==='settings')renderSettings();if(name==='forge'){renderForgeProjects();forge.draw();updateForgeUI()}setTimeout(()=>focusFirstMenuControl(),0)}
 function menuFocusables(){const screen=document.querySelector('.screen.active');if(!screen)return[];return [...screen.querySelectorAll('button:not([disabled]),select:not([disabled]),input:not([disabled]):not([type="hidden"]),[tabindex]:not([tabindex="-1"])')].filter(el=>{const r=el.getBoundingClientRect(),st=getComputedStyle(el);return st.visibility!=='hidden'&&st.display!=='none'&&r.width>1&&r.height>1})}
 function markKeyboardFocus(el){document.querySelectorAll('.keyboard-focus').forEach(x=>x.classList.remove('keyboard-focus'));if(el){el.classList.add('keyboard-focus');el.focus({preventScroll:false})}}
 function focusFirstMenuControl(){if(MC.game?.running)return;const list=menuFocusables();if(list.length&&!list.includes(document.activeElement))markKeyboardFocus(list[0])}
 function moveMenuFocus(dir){const list=menuFocusables();if(!list.length)return;let cur=document.activeElement;if(!list.includes(cur)){markKeyboardFocus(list[0]);return}const a=cur.getBoundingClientRect(),ax=a.left+a.width/2,ay=a.top+a.height/2;let best=null,bestScore=Infinity;for(const el of list){if(el===cur)continue;const b=el.getBoundingClientRect(),bx=b.left+b.width/2,by=b.top+b.height/2,dx=bx-ax,dy=by-ay;if(dir==='left'&&dx>=-2||dir==='right'&&dx<=2||dir==='up'&&dy>=-2||dir==='down'&&dy<=2)continue;const primary=(dir==='left'||dir==='right')?Math.abs(dx):Math.abs(dy),cross=(dir==='left'||dir==='right')?Math.abs(dy):Math.abs(dx),score=primary+cross*1.8;if(score<bestScore){bestScore=score;best=el}}if(best)markKeyboardFocus(best)}
 addEventListener('keydown',e=>{if(MC.game?.inventoryOpen||MC.game?.quizOpen)return;if(MC.game?.running&&!MC.game?.paused)return;const tag=(e.target?.tagName||'').toLowerCase();if(['input','textarea','select'].includes(tag))return;const map={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'};if(map[e.code]){e.preventDefault();moveMenuFocus(map[e.code]);return}if(e.code==='Enter'||e.code==='Space'){const list=menuFocusables(),el=document.activeElement;if(list.includes(el)){e.preventDefault();el.click()}}})
 function avatarAll(){const a=MC.state.data.avatar;MC.avatar.render(q('home-avatar'),a);MC.avatar.render(q('top-avatar'),a,{portrait:true});MC.avatar.render(q('creator-avatar'),a);MC.avatar.render(q('hud-avatar'),a,{portrait:true});const pet=a.pet||'drone';document.querySelectorAll('.drone').forEach(d=>{d.style.display=pet==='none'?'none':'grid';d.dataset.pet=pet;d.classList.add('pet-art-mode');d.innerHTML=MC.petArt?.imgHTML(pet,'pet-art-large')||''})}
 function renderHome(){const d=MC.state.data,h=heroDef();avatarAll();q('profile-name').textContent=d.profile.name;q('profile-level').textContent=d.profile.level;q('lives-top').textContent=d.profile.lives;q('coins-top').textContent=d.profile.coins.toLocaleString('es-AR');q('crystals-top').textContent=d.profile.crystals;q('stars-top').textContent=MC.state.currencyAmount?MC.state.currencyAmount('stars'):MC.state.starsTotal();q('xp-fill').style.width=Math.min(100,d.profile.xp/d.profile.xpNext*100)+'%';q('home-hero-base').textContent=h.name.toUpperCase();q('home-hero-ability').textContent='Q · '+h.ability;const next=d.progress.unlocked||1,wi=Math.ceil(next/5)-1;q('featured-world').textContent=CAMPAIGN[Math.min(7,wi)].name;q('mission-label').textContent=`Nivel ${next}: ${levelName(next)}`;q('mission-fill').style.width=((next-1)%5+1)*18+'%'}
 document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.nav)));document.querySelectorAll('[data-world-jump]').forEach(b=>b.addEventListener('click',()=>{selectedWorld=Math.max(0,+b.dataset.worldJump-1);nav('campaign')}));
