 let storeCategory='rotacion',storeSelectedId='skin:polar_scout';
 function storeDayKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
 function hashText(t){let h=2166136261;for(const ch of String(t)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
 function rotatedStoreItems(){const date=storeDayKey(),pool=STORE_ITEMS.filter(x=>!x.repeat),seed=hashText(date+'MundoCuadroNova');return pool.map((x,i)=>({x,k:(Math.imul((seed^(i*2654435761))>>>0,2246822519)>>>0)})).sort((a,b)=>a.k-b.k).slice(0,10).map(v=>v.x)}
 function rarityOf(it){if(it.rare)return it.rare;if(it.currency==='stars')return'legendary';if(it.currency==='crystals')return it.price>=7?'epic':'rare';if(it.price>=900)return'rare';return'common'}
 function rarityLabel(r){return({common:'COMÚN',rare:'RARO',epic:'ÉPICO',legendary:'LEGENDARIO',mythic:'MÍTICO'})[r]||String(r||'COMÚN').toUpperCase()}
 function rotationPrice(it){if(!rotatedStoreItems().some(x=>x.id===it.id))return it.price;if(it.currency==='coins')return Math.max(1,Math.round(it.price*.85/10)*10);return Math.max(1,it.price-1)}
 function rotationCountdown(){const n=new Date(),e=new Date(n);e.setHours(24,0,0,0);const ms=e-n,h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000);return `${h}h ${String(m).padStart(2,'0')}m`}
 function previewConfig(it){const cfg=JSON.parse(JSON.stringify(MC.state.data.avatar));if(!it)return cfg;const [type,id]=it.id.split(':');if(type==='skin'&&FULL_SKINS[id])Object.assign(cfg,FULL_SKINS[id].cfg);else if(type==='hero'){const h=CAT.heroBases.find(x=>x.id===id);if(h){cfg.heroBase=id;if(h.look){cfg.outfit=h.look.outfit;cfg.outfitColor=h.look.outfitColor}}}else if(type==='outfit'){cfg.outfit=+id;cfg.outfitColor=CAT.outfitColors[+id%CAT.outfitColors.length]}else if(type==='accessory')cfg.accessory=+id;else if(type==='shoes')cfg.shoes=+id;else if(type==='armor')cfg.armor=+id;else if(type==='pet')cfg.pet=id;return cfg}
 function renderStorePreview(it){const box=q('store-preview');if(!box)return;it=it||STORE_ITEMS.find(x=>x.id===storeSelectedId)||rotatedStoreItems()[0]||STORE_ITEMS[0];storeSelectedId=it.id;const rarity=rarityOf(it),cfg=previewConfig(it),visual=['skin','hero','outfit','accessory','shoes','armor','pet'].includes(it.id.split(':')[0]);box.className=`store-live-card preview-card rarity-${rarity}`;box.innerHTML=`<div class="live-card-head"><span>PREVIEW ANIMADO</span><b>${rarityLabel(rarity)}</b></div><div class="store-preview-stage">${visual?MC.avatar.imgHTML(cfg,{alt:it.name}):`<div class="store-preview-icon">${it.art}</div>`}<span class="preview-glow"></span></div><div class="preview-copy"><strong>${it.name}</strong><small>${it.fullSkin?'LOOK COMPLETO · se equipa en un toque':it.desc}</small></div>`}
 function renderDailyEconomy(){const daily=q('store-daily'),missions=q('store-missions'),st=MC.state.dailyStatus(),next=Math.max(1,Math.min(7,st.nextStreak||1)),rewards=[['🪙',120,'monedas'],['💎',2,'cristales'],['🪙',180,'monedas'],['💎',3,'cristales'],['🪙',260,'monedas'],['💎',4,'cristales'],['⭐',1,'estrella']],[ic,am,lab]=rewards[next-1];daily.innerHTML=`<div class="live-card-head"><span>🎁 RECOMPENSA DIARIA</span><b>RACHA ${st.streak}/7</b></div><strong>${st.claimed?'✓ Recompensa de hoy cobrada':`${ic} ${am} ${lab}`}</strong><small>${st.claimed?'Volvé mañana para seguir la racha.':`Día ${next} · el día 7 entrega una estrella de prestigio.`}</small><button class="btn primary" ${st.claimed?'disabled':''}>${st.claimed?'COBRADO':'COBRAR AHORA'}</button>`;const db=daily.querySelector('button');if(db)db.onclick=()=>{const r=MC.state.claimDailyReward();q('store-message').textContent=r.ok?`🎁 Recompensa diaria: ${currencyIcon(r.reward.kind)} ${r.reward.amount}`:'Ya cobraste la recompensa de hoy.';renderStore()};missions.innerHTML=`<div class="live-card-head"><span>🎯 MISIONES DEL DÍA</span><b>REINICIAN HOY</b></div><div class="daily-mission-list">${st.missions.map(m=>`<button class="daily-mission ${m.claimed?'done':''}" data-mid="${m.id}" ${m.claimed||m.progress<m.target?'disabled':''}><span>${m.icon}</span><i><b>${m.label}</b><small>${m.progress}/${m.target} · ${currencyIcon(m.reward.kind)} ${m.reward.amount}</small></i><em>${m.claimed?'✓':m.progress>=m.target?'COBRAR':'EN CURSO'}</em></button>`).join('')}</div>`;missions.querySelectorAll('[data-mid]').forEach(b=>b.onclick=()=>{const r=MC.state.claimDailyMission(b.dataset.mid);q('store-message').textContent=r.ok?`✓ Misión cobrada: ${currencyIcon(r.reward.kind)} ${r.reward.amount}`:'Todavía no completaste esa misión.';renderStore()})}
 function storeEquipped(key){const a=MC.state.data.avatar,inv=MC.state.data.inventory,[type,id]=key.split(':');if(type==='hero')return a.heroBase===id;if(type==='outfit')return a.outfit===+id;if(type==='shoes')return a.shoes===+id;if(type==='accessory')return a.accessory===+id;if(type==='armor')return a.armor===+id;if(type==='pet')return a.pet===id;if(type==='skin')return a.activeSkin===id;if(type==='skill')return inv.equippedSkill===id;if(type==='tool')return inv.equippedTool===id;if(type==='gear'){const g=MC.GEAR_CATALOG?.[id];return !!g&&inv.equippedGear?.[g.slot]===id}return false}
 function equipStoreKey(key){const [type,id]=key.split(':');if(type==='skin'&&FULL_SKINS[id]){Object.assign(MC.state.data.avatar,FULL_SKINS[id].cfg,{activeSkin:id});MC.state.save();avatarAll();return}if(type==='skill'){MC.state.equipSkill(id);return}if(type==='tool'){MC.state.equipTool(id);return}if(type==='gear'){MC.state.equipGear(id);return}equipKey(key)}
 function grantStoreReward(it){const r=it.reward||{};if(r.item)MC.state.addItem(r.item,r.amount||1);if(r.materials)for(const [k,n] of Object.entries(r.materials))MC.state.addMaterial(k,n)}
 function renderStore(){const grid=q('store-grid'),tabs=q('store-tabs'),wallet=q('store-wallet'),msg=q('store-message');wallet.innerHTML=`<span>🪙 <b>${MC.state.currencyAmount('coins').toLocaleString('es-AR')}</b><small>MONEDAS</small></span><span>💎 <b>${MC.state.currencyAmount('crystals')}</b><small>CRISTALES</small></span><span>⭐ <b>${MC.state.currencyAmount('stars')}</b><small>ESTRELLAS</small></span>`;renderDailyEconomy();const cats=[['rotacion',`⏱ HOY · ${rotationCountdown()}`],['destacados','✨ Destacados'],['personajes','🧑 Personajes'],['ropa','👕 Ropa/Skins'],['mascotas','🐾 Mascotas'],['habilidades','⚡ Habilidades'],['herramientas','🛠 Herramientas'],['objetos','🎒 Objetos']];tabs.innerHTML='';for(const [id,label] of cats){const b=document.createElement('button');b.className='store-tab '+(storeCategory===id?'active':'');b.textContent=label;b.onclick=()=>{storeCategory=id;renderStore()};tabs.appendChild(b)}grid.innerHTML='';let list=storeCategory==='rotacion'?rotatedStoreItems():storeCategory==='destacados'?STORE_ITEMS.filter(x=>rarityOf(x)!=='common'||['hero:mage','pet:phoenix','skill:triple_jump','tool:nova_scanner'].includes(x.id)).slice(0,16):STORE_ITEMS.filter(x=>x.cat===storeCategory);const rotationIds=new Set(rotatedStoreItems().map(x=>x.id));for(const it of list){const owned=!it.repeat&&MC.state.owns(it.id),equipped=owned&&storeEquipped(it.id),rarity=rarityOf(it),rotated=rotationIds.has(it.id),price=rotated?rotationPrice(it):it.price,card=document.createElement('article');card.className=`store-item rarity-${rarity} ${owned?'owned':''} ${storeSelectedId===it.id?'selected':''}`;const cost=`${currencyIcon(it.currency)} ${price}`,oldCost=rotated&&price<it.price?`${currencyIcon(it.currency)} ${it.price}`:'';card.innerHTML=`<div class="rarity-ribbon">${rarityLabel(rarity)}</div>${rotated?'<div class="rotation-badge">HOY</div>':''}<div class="store-art">${it.art}</div><div class="store-copy"><div class="store-kind">${it.cat.toUpperCase()}${it.fullSkin?' · SKIN COMPLETA':''}</div><b>${it.name}</b><p>${it.desc}</p><div class="store-cost">${it.repeat?cost:owned?'✓ DESBLOQUEADO':`${oldCost?`<del>${oldCost}</del> `:''}${cost}`}</div></div><button class="btn store-buy ${equipped?'':'primary'}">${it.repeat?'COMPRAR':equipped?'EQUIPADO':owned?'EQUIPAR':'COMPRAR'}</button>`;card.onclick=e=>{if(e.target.closest('button'))return;storeSelectedId=it.id;renderStorePreview(it);document.querySelectorAll('.store-item.selected').forEach(x=>x.classList.remove('selected'));card.classList.add('selected')};const btn=card.querySelector('.store-buy');btn.onclick=e=>{e.stopPropagation();msg.textContent='';storeSelectedId=it.id;renderStorePreview(it);if(it.repeat){if(!MC.state.spendCurrency(it.currency,price)){msg.textContent=`Te faltan ${currencyIcon(it.currency)} para comprar ${it.name}.`;return}grantStoreReward(it);msg.textContent=`✓ ${it.name} agregado al inventario.`;renderStore();renderHome();return}if(owned){equipStoreKey(it.id);msg.textContent=storeEquipped(it.id)?`✓ ${it.name} equipado.`:`${it.name} guardado en tu colección.`;renderStore();avatarAll();renderHome();return}const r=MC.state.purchase(it.id,it.currency,price);if(!r.ok){msg.textContent=r.reason==='funds'?`Te faltan ${currencyIcon(it.currency)} para desbloquear ${it.name}.`:'Ya lo tenés.';return}if(it.id==='hero:mage')MC.state.unlock('outfit:33');if(it.id==='hero:skyblade')MC.state.unlock('outfit:34');if(it.id==='hero:shadow')MC.state.unlock('outfit:35');equipStoreKey(it.id);msg.textContent=`🎉 ${it.name} desbloqueado y equipado.`;renderStore();renderCollection();avatarAll();renderHome()};grid.appendChild(card)}if(!list.length)grid.innerHTML='<div class="store-empty">No hay artículos en esta categoría todavía.</div>';renderStorePreview(STORE_ITEMS.find(x=>x.id===storeSelectedId)||list[0])}
 function equipKey(key){const [type,id]=key.split(':');if(type==='hero')MC.state.data.avatar.heroBase=id;if(['accessory','outfit','shoes','armor'].includes(type))MC.state.data.avatar.activeSkin=null;if(type==='accessory')MC.state.data.avatar.accessory=+id;if(type==='outfit'){MC.state.data.avatar.outfit=+id;MC.state.data.avatar.outfitColor=CAT.outfitColors[+id%CAT.outfitColors.length]}if(type==='shoes')MC.state.data.avatar.shoes=+id;if(type==='armor')MC.state.data.avatar.armor=+id;if(type==='pet')MC.state.data.avatar.pet=id;MC.state.save();avatarAll()}
 // SETTINGS
 function renderSettings(){const d=MC.state.data;q('player-name-input').value=d.profile.name;q('volume-input').value=d.settings.volume;q('volume-value').textContent=`${d.settings.volume}%`;q('reduced-motion').checked=d.settings.reducedMotion;q('always-touch').checked=d.settings.alwaysTouch;q('test-mode').checked=d.settings.testMode;q('show-grid').checked=d.settings.showGrid!==false;q('initial-lives').value=d.settings.initialLives||3;q('initial-continues').value=d.settings.initialContinues??3;q('extra-life-coins').value=d.settings.extraLifeCoins||100;q('difficulty-select').value=d.settings.difficulty||'normal';q('respawn-mode').value=d.settings.respawnMode||'checkpoint';if(q('gamepad-deadzone')){q('gamepad-deadzone').value=Math.round((d.settings.gamepadDeadzone||.18)*100);q('gamepad-deadzone-value').textContent=`${q('gamepad-deadzone').value}%`}if(q('gamepad-vibration'))q('gamepad-vibration').checked=d.settings.gamepadVibration!==false;MC.gamepad?.updateStatus?.()}
 q('volume-input').addEventListener('input',e=>{const v=Math.max(0,Math.min(100,+e.target.value||0));MC.state.data.settings.volume=v;q('volume-value').textContent=`${v}%`;MC.game?.music?.setVolume(v);MC.state.save()});
 q('gamepad-deadzone')?.addEventListener('input',e=>{const v=Math.max(5,Math.min(45,+e.target.value||18));MC.state.data.settings.gamepadDeadzone=v/100;q('gamepad-deadzone-value').textContent=`${v}%`;MC.state.save()});q('gamepad-vibration')?.addEventListener('change',e=>{MC.state.data.settings.gamepadVibration=!!e.target.checked;MC.state.save();if(e.target.checked)MC.gamepad?.rumble?.(.22,.18,70)});
 const fullSaveExport=q('full-save-export'),fullSaveImport=q('full-save-import'),fullSaveStatus=q('full-save-status');
 if(fullSaveExport)fullSaveExport.onclick=()=>{try{MC.state.save();const pack=MC.state.exportSave(),date=new Date().toISOString().slice(0,10),name=(MC.state.data.profile.name||'Jugador').replace(/[^a-z0-9_-]+/gi,'_');MC.platform?.downloadText?.(`MundoCuadro_${name}_${date}.json`,JSON.stringify(pack,null,2),'application/json');fullSaveStatus.textContent='✓ Copia de partida generada.'}catch(e){fullSaveStatus.textContent='No pude generar la copia: '+e.message}};
 if(fullSaveImport)fullSaveImport.onchange=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{MC.state.importSave(String(r.result||''));fullSaveStatus.textContent='✓ Partida restaurada. Recargando…';setTimeout(()=>location.reload(),450)}catch(err){fullSaveStatus.textContent='No pude restaurar esa partida: '+err.message}};r.onerror=()=>fullSaveStatus.textContent='No pude leer el archivo.';r.readAsText(f);e.target.value=''};
 q('legacy-import-btn').onclick=()=>{const f=q('legacy-save-input').files?.[0];if(!f){q('legacy-import-status').textContent='Elegí savegame_v5.json';return}const r=new FileReader();r.onload=()=>{try{const old=JSON.parse(r.result),d=MC.state.data;d.progress.unlocked=Math.max(1,Math.min(40,+old.unlocked_level||1));d.progress.completed=Array.isArray(old.completed_levels)?old.completed_levels.map(Number).filter(n=>n>=1&&n<=40):[];d.progress.stars={};for(const [k,v] of Object.entries(old.level_stars||{}))d.progress.stars[+k]=Math.max(0,Math.min(3,+v||0));d.profile.coins=Math.max(d.profile.coins,+old.total_coins||0);d.profile.crystals=Math.max(d.profile.crystals,+old.boss_cores||0);const a=d.avatar;a.hair=(+old.style_hair||0)%CAT.hair.length;a.hairColor=CAT.hairColor[(+old.style_hair_color||0)%CAT.hairColor.length];a.outfit=(+old.style_outfit||0)%CAT.outfits.length;a.outfitColor=CAT.outfitColors[a.outfit%CAT.outfitColors.length];a.shoes=(+old.style_shoes||0)%CAT.shoes.length;a.accessory=(+old.style_accessory||0)%CAT.accessories.length;a.skin=CAT.skins[(+old.style_skin||0)%CAT.skins.length];a.face=(+old.style_face||0)%CAT.faces.length;a.body=(+old.style_body||0)%4;d.profile.totalStars=MC.state.starsTotal();d.profile.starTokens=Math.max(d.profile.starTokens||0,d.profile.totalStars);MC.state.save();q('legacy-import-status').textContent=`✓ Importado: nivel ${d.progress.unlocked}, ${MC.state.starsTotal()} estrellas`;renderHome()}catch(e){q('legacy-import-status').textContent='No pude leer ese save.'}};r.readAsText(f)};
 q('save-settings').onclick=()=>{const d=MC.state.data;d.profile.name=(q('player-name-input').value.trim()||'Jugador').slice(0,20);d.settings.volume=+q('volume-input').value;d.settings.reducedMotion=q('reduced-motion').checked;d.settings.alwaysTouch=q('always-touch').checked;d.settings.testMode=q('test-mode').checked;d.settings.showGrid=q('show-grid').checked;d.settings.initialLives=Math.max(1,Math.min(9,+q('initial-lives').value||3));d.settings.initialContinues=Math.max(0,Math.min(9,+q('initial-continues').value||0));d.settings.extraLifeCoins=Math.max(25,Math.min(500,+q('extra-life-coins').value||100));d.settings.difficulty=q('difficulty-select').value;d.settings.respawnMode=q('respawn-mode').value;d.settings.gamepadDeadzone=Math.max(.05,Math.min(.45,(+q('gamepad-deadzone')?.value||18)/100));d.settings.gamepadVibration=q('gamepad-vibration')?.checked!==false;document.body.classList.toggle('reduced-motion',d.settings.reducedMotion);q('touch-controls').style.display=d.settings.alwaysTouch?'flex':'';MC.state.save();renderHome();nav('home')};
 q('apply-run-resources').onclick=()=>{const d=MC.state.data;d.settings.initialLives=Math.max(1,Math.min(9,+q('initial-lives').value||3));d.settings.initialContinues=Math.max(0,Math.min(9,+q('initial-continues').value||0));d.settings.extraLifeCoins=Math.max(25,Math.min(500,+q('extra-life-coins').value||100));d.settings.difficulty=q('difficulty-select').value;d.settings.respawnMode=q('respawn-mode').value;MC.state.applyRunSettings();q('apply-run-resources').textContent=`✓ ${d.profile.lives} VIDAS · ${d.profile.continues} CONTINUES`;setTimeout(()=>q('apply-run-resources').textContent='APLICAR VIDAS/CONTINUES AHORA',1200);renderHome()};
 addEventListener('mcgamepadaxes',e=>{if(!q('screen-forge')?.classList.contains('active'))return;const {aimX=0,aimY=0}=e.detail||{};if(Math.abs(aimX)<.12&&Math.abs(aimY)<.12)return;forge.cam.x+=aimX*18/Math.max(.35,forge.zoom);forge.cam.y+=aimY*18/Math.max(.35,forge.zoom);forge.draw()});
 MC.androidBack=()=>{
  const active=document.querySelector('.screen.active')?.dataset?.screen||'home';
  if(active==='game'){
    if(MC.game?.inventoryOpen){MC.game.toggleInventory?.(false);return true}
    const quiz=q('wizard-quiz-overlay');if(quiz&&!quiz.classList.contains('hidden')){quiz.classList.add('hidden');MC.game.paused=false;return true}
    const briefing=q('bonus-briefing-overlay');if(briefing&&!briefing.classList.contains('hidden')){briefing.classList.add('hidden');game.paused=false;return true}
    const complete=q('level-complete');if(complete&&!complete.classList.contains('hidden')){return true}
    if(MC.game?.running&&!MC.game?.paused){MC.game.togglePause(true);return true}
    if(MC.game?.paused){MC.game.running=false;MC.game.togglePause(false);nav(currentMode==='forge'?'forge':'campaign');return true}
  }
  if(active!=='home'){nav('home');return true}
  return false;
 };
